-- Bandly's own Artist DNA. The platform dogfoods its own 20-question
-- intake so the login screen can show the platform's philosophy —
-- components, brand mantra, archetype — generated by the exact same
-- pipeline every artist uses. Fixed UUID so backend (PlatformBand) and
-- frontend both address it without a lookup.
insert into bands (id, name, plan_tier)
values ('00000000-0000-0000-0000-00000000ba11', 'Bandly', 'platform')
on conflict (id) do nothing;

-- The richer profile fields the 20-question intake produces, reasoned in
-- the same generation call as the bios. Nullable / defaulted: DNA versions
-- generated before this migration won't have them.
alter table artist_dna_versions
    add column brand_mantra      text,
    add column primary_archetype varchar(60),
    add column dna_components    jsonb not null default '[]'::jsonb;
